function solve(nums) {
  nums.sort((a,b) => a - b);
  for (let i = 1; i < nums.length; i++) if (nums[i] === nums[i-1]) return true;
  return false;
}

function solve(nums) {
  return new Set(nums).size !== nums.length;
}

